import base64
import json
import struct
from pathlib import Path
from typing import Any

import numpy as np
import trimesh

from cgraph.library import DataPort, ExeNodeType, FlowPort


class StlGeometryImport(ExeNodeType):
    id = 'stl_geometry_import'
    version = '0.1.0'
    source = 'stl_geometry_import'
    display_name = 'STL 几何导入'
    description = '读取 STL 机翼文件并生成可供后续网格划分使用的表面几何网格。'
    category = 'dataio.cad'
    receive = (FlowPort(name='upstream'),)
    send = (FlowPort(name='downstream'),)
    inputs = (
        DataPort(
            name='geometry_file',
            dtype='file',
            display_name='STL 文件',
            description='外部 STL 机翼几何文件路径。',
            semantic_type='filesystem.file',
            extensions={'artifact_contract': {'format': 'stl_geometry_file_v1'}},
        ),
    )
    outputs = (
        DataPort(
            name='surface_mesh',
            dtype='mesh',
            display_name='表面几何网格',
            description='由 STL 读取的机翼三角形表面网格。',
            semantic_type='geometry.surface_mesh',
            extensions={'artifact_contract': {'format': 'surface_mesh_v1'}},
        ),
    )

    @staticmethod
    def _read_geometry_input(geometry_file: Any) -&gt; tuple[bytes, str]:
        if isinstance(geometry_file, dict):
            content = geometry_file.get('content')
            encoding = geometry_file.get('encoding')
            filename = geometry_file.get('filename')
            suffix = geometry_file.get('suffix')
            if not isinstance(content, str) or not content:
                raise ValueError('geometry_file artifact content must be a non-empty string')
            if not isinstance(filename, str) or not filename.strip():
                raise ValueError('geometry_file artifact filename must be a non-empty string')
            if suffix != '.stl':
                raise ValueError('geometry_file artifact suffix must be .stl')
            if encoding == 'utf-8':
                data = content.encode('utf-8')
            elif encoding == 'base64':
                try:
                    data = base64.b64decode(content, validate=True)
                except (ValueError, base64.binascii.Error) as exc:
                    raise ValueError('geometry_file artifact is not valid base64') from exc
            else:
                raise ValueError('geometry_file artifact encoding must be utf-8 or base64')
            if not data:
                raise ValueError('geometry_file artifact content decodes to an empty file')
            return data, Path(filename).name

        if not isinstance(geometry_file, str) or not geometry_file.strip():
            raise ValueError('geometry_file must be a non-empty string path or STL artifact')
        path = Path(geometry_file)
        if '..' in path.parts:
            raise ValueError('geometry_file path traversal is not allowed')
        if path.suffix.lower() != '.stl':
            raise ValueError('geometry_file must have an .stl suffix')
        try:
            data = path.read_bytes()
        except (OSError, ValueError) as exc:
            raise ValueError('controlled STL file cannot be read') from exc
        if not data:
            raise ValueError('controlled STL file is empty')
        return data, path.name

    @staticmethod
    def _parse_ascii(data: bytes) -&gt; list[tuple[tuple[float, float, float], ...]]:
        text = data.decode('ascii', errors='ignore')
        triangles: list[tuple[tuple[float, float, float], ...]] = []
        current: list[tuple[float, float, float]] | None = None
        for raw_line in text.splitlines():
            line = raw_line.strip()
            lower = line.lower()
            if lower == 'facet' or lower.startswith('facet '):
                if current is not None:
                    raise ValueError('ASCII STL contains a nested facet')
                current = []
            elif lower.startswith('vertex '):
                if current is None:
                    raise ValueError('ASCII STL vertex is outside a facet')
                fields = line.split()
                if len(fields) != 4 or len(current) &gt;= 3:
                    raise ValueError('ASCII STL vertex record is invalid')
                try:
                    point = tuple(float(value) for value in fields[1:4])
                except ValueError as exc:
                    raise ValueError('ASCII STL vertex contains a non-numeric value') from exc
                current.append(point)  # type: ignore[arg-type]
            elif lower == 'endfacet':
                if current is None or len(current) != 3:
                    raise ValueError('ASCII STL facet must contain exactly three vertices')
                triangles.append(tuple(current))
                current = None
        if current is not None:
            raise ValueError('ASCII STL ends before endfacet')
        if not triangles:
            raise ValueError('STL contains no triangles')
        return triangles

    @staticmethod
    def _parse_binary(data: bytes) -&gt; list[tuple[tuple[float, float, float], ...]]:
        if len(data) &lt; 84:
            raise ValueError('binary STL is shorter than its header')
        count = struct.unpack_from('&lt;I', data, 80)[0]
        expected_length = 84 + 50 * count
        if count == 0:
            raise ValueError('STL contains no triangles')
        if expected_length != len(data):
            raise ValueError('binary STL length does not match its triangle count')
        triangles: list[tuple[tuple[float, float, float], ...]] = []
        offset = 84
        for _ in range(count):
            try:
                values = struct.unpack_from('&lt;12f', data, offset + 12)
            except struct.error as exc:
                raise ValueError('binary STL triangle record is truncated') from exc
            triangles.append((
                (float(values[0]), float(values[1]), float(values[2])),
                (float(values[3]), float(values[4]), float(values[5])),
                (float(values[6]), float(values[7]), float(values[8])),
            ))
            offset += 50
        return triangles

    @staticmethod
    def _parse_stl(data: bytes) -&gt; tuple[list[list[float]], list[list[int]]]:
        text = data.decode('ascii', errors='ignore')
        ascii_markers = any(
            line.strip().lower().startswith(('facet ', 'vertex '))
            for line in text.splitlines()
        )
        raw_triangles = StlGeometryImport._parse_ascii(data) if ascii_markers else StlGeometryImport._parse_binary(data)

        vertices: list[list[float]] = []
        vertex_indices: dict[tuple[float, float, float], int] = {}
        triangles: list[list[int]] = []
        for raw_triangle in raw_triangles:
            indices: list[int] = []
            for raw_point in raw_triangle:
                point_array = np.asarray(raw_point, dtype=np.float64)
                if point_array.shape != (3,) or not bool(np.isfinite(point_array).all()):
                    raise ValueError('STL contains a non-finite vertex')
                point = tuple(float(value) for value in point_array)
                index = vertex_indices.get(point)
                if index is None:
                    index = len(vertices)
                    vertex_indices[point] = index
                    vertices.append(list(point))
                indices.append(index)
            coordinates = np.asarray([vertices[index] for index in indices], dtype=np.float64)
            cross_product = np.cross(coordinates[1] - coordinates[0], coordinates[2] - coordinates[0])
            if not bool(np.isfinite(cross_product).all()) or float(np.linalg.norm(cross_product)) == 0.0:
                raise ValueError('STL contains a degenerate triangle')
            triangles.append(indices)

        mesh = trimesh.Trimesh(
            vertices=np.asarray(vertices, dtype=np.float64),
            faces=np.asarray(triangles, dtype=np.int64),
            process=False,
        )
        if mesh.is_empty or not np.isfinite(float(mesh.area)) or float(mesh.area) &lt;= 0.0:
            raise ValueError('STL does not contain a valid non-zero-area surface mesh')
        normalized_vertices = [
            [float(value) for value in row]
            for row in np.asarray(mesh.vertices, dtype=np.float64)
        ]
        normalized_triangles = [
            [int(value) for value in row]
            for row in np.asarray(mesh.faces, dtype=np.int64)
        ]
        return normalized_vertices, normalized_triangles

    @staticmethod
    def run(geometry_file) -&gt; dict[str, Any]:
        data, input_filename = StlGeometryImport._read_geometry_input(geometry_file)
        vertices, triangles = StlGeometryImport._parse_stl(data)
        payload = {
            'format': 'surface_mesh_v1',
            'vertices': vertices,
            'triangles': triangles,
        }
        content = json.dumps(payload, ensure_ascii=False, separators=(',', ':'), allow_nan=False)
        stem = Path(input_filename).stem
        if not stem:
            raise ValueError('STL filename has no usable stem')
        return {
            'surface_mesh': {
                'filename': f'{stem}_surface.mesh.json',
                'content': content,
                'encoding': 'utf-8',
                'suffix': '.mesh.json',
            }
        }

